ption":"An invitee\'s registration for an event a VTA holds. At most one per invitee per event (VTI-EVT-030).","type":"object","additionalProperties":false,"required":["registrationId","eventId","registrantDid","status","guests","roster","eventSequence","createdAt","updatedAt"],"properties":{"registrationId":{"\$ref":"#/\$defs/RegistrationId"},"eventId":{"\$ref":"#/\$defs/EventId"},"registrantDid":{"\$ref":"#/\$defs/VtaEventDid","description":"The invitee\'s identifier. Shown to the principal and the registrant alone (VTI-PEV-024)."},"displayName":{"\$ref":"#/\$defs/VtaEventDisplayName"},"status":{"\$ref":"#/\$defs/RegistrationStatus"},"guests":{"type":"integer","minimum":0,"maximum":10},"answers":{"\$ref":"#/\$defs/RegistrationAnswers","description":"Present only to the principal and the registrant (VTI-PEV-041)."},"codeOfConductAcknowledged":{"type":"string","pattern":"^[0-9a-f]{64}\$"},"waitlistPosition":{"type":"integer","minimum":1},"roster":{"\$ref":"#/\$defs/VtaEventRoster","description":"The roster setting the registration was made under (VTI-EVT-052)."},"eventSequence":{"type":"integer","minimum":0,"description":"The event\'s `sequence` when the registration last changed."},"note":{"type":"string","maxLength":500,"description":"A note the principal gave with a decision, shown to the registrant."},"createdAt":{"\$ref":"#/\$defs/EventInstant"},"updatedAt":{"\$ref":"#/\$defs/EventInstant"}}},"VtaEventRoster":{"title":"VtaEventRoster","description":"The roster setting of an event a VTA holds: `visible`, in which registrants who are `going` or `maybe` see one another by display name; or `hidden`, in which no registrant sees another. Fixed at publish (VTI-EVT-051). A VTA offers no `anonymous` (VTI-PEV-002).","type":"string","enum":["visible","hidden"]},"VtaEventDid":{"title":"VtaEventDid","description":"A DID: the event\'s host (a persona identifier the principal holds), or an invitee\'s identifier.","type":"string","minLength":7,"maxLength":2048,"pattern":"^did: